public class OOPBasicsDemo {
    public static void main(String[] args) {
        // Declared type Account, runtime types StudentAccount and SavingsAccount
        Account[] accounts = {
            new StudentAccount("Riley", 120.00),
            new SavingsAccount("Jordan", 500.00, 0.02),
        };
        for (Account account : accounts) {
            account.deposit(30.00);
            // Dynamic dispatch: StudentAccount's override applies its per-withdrawal limit
            boolean ok = account.withdraw(150.00);
            System.out.println(account.getOwner() + " (" + account.kind() + ") withdraw $150.00: "
                + (ok ? "approved" : "declined"));
            if (account instanceof SavingsAccount savings) {
                savings.addInterest();      // only savings accounts have this capability
            }
            System.out.println(account.summary());
        }
    }
}

// Encapsulation: balance is private and only changes through validated methods
class Account {
    private final String owner;
    private double balance;

    Account(String owner, double openingBalance) {
        this.owner = owner;
        this.balance = openingBalance;
    }

    String getOwner() { return owner; }

    double getBalance() { return balance; }

    void deposit(double amount) {
        if (amount > 0) balance += amount;
    }

    boolean withdraw(double amount) {
        if (amount <= 0 || amount > balance) return false;   // balance never goes negative
        balance -= amount;
        return true;
    }

    String kind() { return "Account"; }

    String summary() {
        return owner + " balance=$" + String.format("%.2f", balance);
    }
}

// Inheritance: a StudentAccount is-an Account with a stricter withdraw rule
class StudentAccount extends Account {
    static final double WITHDRAW_LIMIT = 100.00;

    StudentAccount(String owner, double openingBalance) {
        super(owner, openingBalance);
    }

    @Override
    boolean withdraw(double amount) {
        if (amount > WITHDRAW_LIMIT) return false;
        return super.withdraw(amount);   // reuse the parent's checks
    }

    @Override
    String kind() { return "Student"; }
}

class SavingsAccount extends Account {
    private final double rate;

    SavingsAccount(String owner, double openingBalance, double rate) {
        super(owner, openingBalance);
        this.rate = rate;
    }

    void addInterest() {
        deposit(getBalance() * rate);    // goes through the public API, not the private field
    }

    @Override
    String kind() { return "Savings"; }
}

