#include <cstdio>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

class Account {
    std::string owner;
    double balance;

public:
    Account(std::string owner, double openingBalance)
        : owner(std::move(owner)), balance(openingBalance) {}
    virtual ~Account() = default;  // needed when deleting through a base pointer

    const std::string& getOwner() const { return owner; }
    double getBalance() const { return balance; }

    void deposit(double amount) {
        if (amount > 0) balance += amount;
    }

    // C++ methods are not virtual unless declared so; Java's are virtual by default
    virtual bool withdraw(double amount) {
        if (amount <= 0 || amount > balance) return false;
        balance -= amount;
        return true;
    }

    virtual std::string kind() const { return "Account"; }

    std::string summary() const {
        char buf[64];
        std::snprintf(buf, sizeof buf, " balance=$%.2f", balance);
        return owner + buf;
    }
};

class StudentAccount : public Account {
public:
    static constexpr double WITHDRAW_LIMIT = 100.00;
    using Account::Account;  // inherit the constructor

    bool withdraw(double amount) override {
        if (amount > WITHDRAW_LIMIT) return false;
        return Account::withdraw(amount);  // like super.withdraw
    }

    std::string kind() const override { return "Student"; }
};

class SavingsAccount : public Account {
    double rate;

public:
    SavingsAccount(std::string owner, double openingBalance, double rate)
        : Account(std::move(owner), openingBalance), rate(rate) {}

    void addInterest() { deposit(getBalance() * rate); }

    std::string kind() const override { return "Savings"; }
};

int main() {
    std::vector<std::unique_ptr<Account>> accounts;
    accounts.push_back(std::make_unique<StudentAccount>("Riley", 120.00));
    accounts.push_back(std::make_unique<SavingsAccount>("Jordan", 500.00, 0.02));

    for (auto& account : accounts) {
        account->deposit(30.00);
        bool ok = account->withdraw(150.00);
        std::cout << account->getOwner() << " (" << account->kind() << ") withdraw $150.00: "
                  << (ok ? "approved" : "declined") << "\n";
        // dynamic_cast is C++'s checked downcast, like Java's instanceof pattern
        if (auto* savings = dynamic_cast<SavingsAccount*>(account.get())) {
            savings->addInterest();
        }
        std::cout << account->summary() << "\n";
    }
}

