import java.util.ArrayList;
import java.util.List;

public class EncapsulationAccount {
    static void report(String action, boolean ok, BankAccount acct) {
        System.out.println(action + " -> " + (ok ? "ok" : "rejected")
            + ", balance $" + String.format("%.2f", acct.getBalance()));
    }

    public static void main(String[] args) {
        BankAccount acct = new BankAccount("Ana", 100.00);
        System.out.println("opened for " + acct.getOwner() + " with $" + String.format("%.2f", acct.getBalance()));
        report("deposit 50.00", acct.deposit(50.00), acct);
        report("withdraw 200.00", acct.withdraw(200.00), acct);
        report("withdraw -5.00", acct.withdraw(-5.00), acct);
        report("withdraw 90.00", acct.withdraw(90.00), acct);

        try {
            new BankAccount("Bo", -20.00);
        } catch (IllegalArgumentException e) {
            System.out.println("new BankAccount(\"Bo\", -20.00) -> rejected: " + e.getMessage());
        }

        List<String> copy = acct.getHistory();
        copy.add("withdraw 1000000.00");   // edits the caller's copy only
        System.out.println("caller's copy has " + copy.size() + " entries");
        System.out.println("account history: " + acct.getHistory());
    }
}

class BankAccount {
    private final String owner;
    private double balance;                       // invariant: balance >= 0
    private final List<String> history = new ArrayList<>();

    BankAccount(String owner, double openingBalance) {
        if (openingBalance < 0) {
            throw new IllegalArgumentException("opening balance must be >= 0");
        }
        this.owner = owner;
        this.balance = openingBalance;
    }

    boolean deposit(double amount) {
        if (amount <= 0) return false;
        balance += amount;
        history.add(String.format("deposit %.2f", amount));
        return true;
    }

    boolean withdraw(double amount) {
        if (amount <= 0 || amount > balance) return false;   // keeps the invariant
        balance -= amount;
        history.add(String.format("withdraw %.2f", amount));
        return true;
    }

    String getOwner() { return owner; }

    double getBalance() { return balance; }   // read access only: there is no setBalance

    List<String> getHistory() {
        return new ArrayList<>(history);       // defensive copy protects the private list
    }
}

