public class InheritanceVehicles {
    public static void main(String[] args) {
        Car car = new Car("Toyota", 4, new Engine(1.8));
        car.start();
        System.out.println(car.describe());

        Bike bike = new Bike("Trek");
        bike.start();                    // inherited unchanged from Vehicle
        System.out.println(bike.describe());

        System.out.println("car instanceof Vehicle: " + (car instanceof Vehicle));
        System.out.println("bike wheels via inherited getter: " + bike.getWheels());
    }
}

class Engine {
    private final double liters;

    Engine(double liters) { this.liters = liters; }

    String start() { return String.format("%.1fL engine running", liters); }
}

class Vehicle {
    protected final String brand;       // visible to subclasses
    private final int wheels;           // hidden even from subclasses

    Vehicle(String brand, int wheels) {
        this.brand = brand;
        this.wheels = wheels;
        System.out.println("Vehicle constructor: " + brand);
    }

    int getWheels() { return wheels; }

    void start() { System.out.println(brand + " starts"); }

    String describe() { return brand + " with " + wheels + " wheels"; }
}

class Car extends Vehicle {             // Car is-a Vehicle
    private final int doors;
    private final Engine engine;        // Car has-an Engine (composition)

    Car(String brand, int doors, Engine engine) {
        super(brand, 4);                // must be the first statement
        this.doors = doors;
        this.engine = engine;
        System.out.println("Car constructor: " + doors + " doors");
    }

    @Override
    void start() {
        super.start();                  // reuse the parent's behavior, then extend it
        System.out.println("  " + engine.start());
    }

    @Override
    String describe() { return super.describe() + " and " + doors + " doors"; }
}

class Bike extends Vehicle {
    Bike(String brand) { super(brand, 2); }
}

