#include <cstdio>
#include <iostream>
#include <string>
#include <type_traits>

class Engine {
    double liters;

public:
    explicit Engine(double liters) : liters(liters) {}

    std::string start() const {
        char buf[48];
        std::snprintf(buf, sizeof buf, "%.1fL engine running", liters);
        return buf;
    }
};

class Vehicle {
protected:
    std::string brand;

private:
    int wheels;

public:
    Vehicle(std::string brand, int wheels) : brand(std::move(brand)), wheels(wheels) {
        std::cout << "Vehicle constructor: " << this->brand << "\n";
    }
    virtual ~Vehicle() = default;

    int getWheels() const { return wheels; }

    virtual void start() const { std::cout << brand << " starts\n"; }

    virtual std::string describe() const { return brand + " with " + std::to_string(wheels) + " wheels"; }
};

class Car : public Vehicle {
    int doors;
    Engine engine;  // has-a

public:
    // The base class is initialized first in the member initializer list, like super(...)
    Car(std::string brand, int doors, Engine engine) : Vehicle(std::move(brand), 4), doors(doors), engine(engine) {
        std::cout << "Car constructor: " << doors << " doors\n";
    }

    void start() const override {
        Vehicle::start();  // C++ names the parent explicitly instead of super
        std::cout << "  " << engine.start() << "\n";
    }

    std::string describe() const override {
        return Vehicle::describe() + " and " + std::to_string(doors) + " doors";
    }
};

class Bike : public Vehicle {
public:
    explicit Bike(std::string brand) : Vehicle(std::move(brand), 2) {}
};

int main() {
    Car car("Toyota", 4, Engine(1.8));
    car.start();
    std::cout << car.describe() << "\n";

    Bike bike("Trek");
    bike.start();
    std::cout << bike.describe() << "\n";

    // C++ checks the is-a relationship on types at compile time
    std::cout << std::boolalpha << "car instanceof Vehicle: " << std::is_base_of_v<Vehicle, Car> << "\n";
    std::cout << "bike wheels via inherited getter: " << bike.getWheels() << "\n";
}

