public class PolymorphismShapes {
    // Overloads: chosen at compile time from the argument's declared type
    static String describe(Shape s) { return "describe(Shape) chosen"; }

    static String describe(Circle c) { return "describe(Circle) chosen"; }

    public static void main(String[] args) {
        Shape[] shapes = {new Circle(1), new Rectangle(3, 4), new Square(2)};
        double total = 0;
        for (Shape s : shapes) {
            // Overrides: chosen at runtime from the object's actual class
            System.out.println(s.name() + " area=" + String.format("%.2f", s.area()));
            total += s.area();
        }
        System.out.println("total area=" + String.format("%.2f", total));

        Shape declaredShape = new Circle(1);
        System.out.println("declaredShape.name() -> " + declaredShape.name() + " (runtime class decides)");
        System.out.println("describe(declaredShape) -> " + describe(declaredShape) + " (declared type decides)");
        System.out.println("describe(new Circle(1)) -> " + describe(new Circle(1)));
    }
}

class Shape {
    double area() { return 0; }

    String name() { return "Shape"; }
}

class Circle extends Shape {
    private final double r;

    Circle(double r) { this.r = r; }

    @Override double area() { return Math.PI * r * r; }

    @Override String name() { return "Circle"; }
}

class Rectangle extends Shape {
    private final double w, h;

    Rectangle(double w, double h) { this.w = w; this.h = h; }

    @Override double area() { return w * h; }

    @Override String name() { return "Rectangle"; }
}

class Square extends Rectangle {
    Square(double side) { super(side, side); }

    @Override String name() { return "Square"; }   // area() is inherited from Rectangle
}

