    explicit Square(int side) : side(side) {}
    std::string draw() const override { return "Square " + std::to_string(side) + "x" + std::to_string(side); }
    void scale(int factor) override { side *= factor; }
    int width() const override { return side; }
    int height() const override { return side; }
